/* ---------- Sign in ---------- */
.sgx{padding:20px;max-width:320px;margin:0 auto;width:100%;overflow:hidden}
.sgx-st{display:flex;flex-direction:column;gap:6px}
.sgx-st>b{font-weight:500;font-size:15px}
.sgx-st>.muted{font-size:12.5px;margin-bottom:8px}
.sgx-st.in{animation:sgin .5s var(--ease) both}
@keyframes sgin{from{opacity:0;transform:translateX(20px);filter:blur(4px)}}
.sgx-f{display:flex;flex-direction:column;gap:5px;font-size:12.5px;font-weight:500}
.sgx-f input{height:40px;border:0;outline:0;border-radius:11px;background:var(--chip);padding:0 12px;font:inherit;font-size:13.5px;font-weight:400;color:var(--fg);transition:box-shadow .25s,background .25s}
.sgx-f input:focus{background:var(--surface);box-shadow:inset 0 0 0 1.5px var(--accent),0 0 0 4px var(--accent-bg)}
.sgx-f.bad input{box-shadow:inset 0 0 0 1.5px var(--bad);animation:sgsh .4s}
@keyframes sgsh{20%,60%{transform:translateX(-4px)}40%,80%{transform:translateX(4px)}}
.sgx-err{font-size:12px;color:var(--bad);min-height:16px}
.sgx-go{height:40px;width:100%}
.sgx-bk{display:flex;align-items:center;gap:6px;font-size:12.5px;color:var(--muted);align-self:flex-start;margin-bottom:6px}
.sgx-bk:hover{color:var(--fg)}
.sgx-code{display:grid;grid-template-columns:repeat(6,1fr);gap:6px}
.sgx-code input{width:100%;height:46px;border:0;outline:0;border-radius:11px;background:var(--chip);text-align:center;font:inherit;font-family:var(--mono);font-size:18px;color:var(--fg);transition:box-shadow .25s,background .25s,transform .3s var(--ease)}
.sgx-code input:focus{background:var(--surface);box-shadow:inset 0 0 0 1.5px var(--accent)}
.sgx-code input.f{transform:scale(1.04)}
.sgx-code{cursor:pointer}
.sgx-code input{caret-color:var(--accent)}
.sgx-code.vf input{animation:sgvf 1s var(--ease-io) infinite;animation-delay:calc(var(--i) * 90ms)}
@keyframes sgvf{50%{background:var(--hover);transform:translateY(-2px)}}
.sgx-code.ok input{background:var(--ok-bg);color:var(--ok);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--ok) 30%,transparent);animation:sgok .5s var(--ease) both;animation-delay:calc(var(--i) * 70ms)}
@keyframes sgok{0%{background:var(--chip);color:var(--fg)}45%{transform:scale(1.1)}100%{transform:none}}
.sgx-v{display:inline-flex;align-items:center;gap:7px;color:var(--fg2)}
.sgx-v .spin{width:11px;height:11px}
.sgx-v.ok{color:var(--ok)}
.sgx-hint{color:var(--fg2)}
.sgx-ck{width:52px;height:52px;fill:none;stroke-width:2.5;stroke-linecap:round;stroke-linejoin:round}
.sgx-ck circle{stroke:var(--ok);stroke-dasharray:151;stroke-dashoffset:151;animation:sgdraw .7s var(--ease) forwards}
.sgx-ck path{stroke:var(--ok);stroke-dasharray:30;stroke-dashoffset:30;animation:sgdraw .4s var(--ease) .55s forwards}
@keyframes sgdraw{to{stroke-dashoffset:0}}
.sgx-bar{width:120px;height:3px;border-radius:2px;background:var(--line);overflow:hidden;margin-top:4px}
.sgx-bar i{display:block;height:100%;width:0;background:var(--ok);animation:sgbar 1.8s var(--ease) .6s forwards}
@keyframes sgbar{to{width:100%}}
.sgx-rs{font-size:12px;margin-top:6px}
.sgx-done{display:flex;flex-direction:column;align-items:center;gap:8px;padding:20px 0;font-size:13px;text-align:center}
.sgx-done>b{font-weight:500;font-size:15px}

DM.def('sign-in', (r, c) => {
  r.innerHTML = r.innerHTML.replace('{l}', I('chev-l','xs'));
  const s1 = $('.sgx-1', r), s2 = $('.sgx-2', r), em = $('.sgx-em', r), err = $('.sgx-err', r), go = $('.sgx-go', r), code = $('.sgx-code', r);
  code.innerHTML = Array.from({ length:6 }, (_, i) => `<input inputmode="numeric" maxlength="1" aria-label="Digit ${i + 1}" style="--i:${i}">`).join('');
  const CODE = '482157';
  const ins = $$('input', code);
  const send = demo => c.run(async () => {
    const v = em.value.trim();
    if (!/^\S+@\S+\.\S+$/.test(v)){ const f = em.parentElement; f.classList.remove('bad'); void f.offsetWidth; f.classList.add('bad'); swap(err, v ? 'That email looks incomplete' : 'Enter your email'); return; }
    em.parentElement.classList.remove('bad'); swap(err, ''); go.innerHTML = '<span class="spin"></span>'; await c.wait(800);
    s1.hidden = true; s2.hidden = false; s2.classList.remove('in'); void s2.offsetWidth; s2.classList.add('in'); $('.sgx-to', r).textContent = v; if (demo !== true) ins[0].focus({ preventScroll:true });
    let n = 30; const ns = $('.sgx-rs .num', r); const iv = c.every(1000, () => { if (checking || !ns.isConnected) return clearInterval(iv); n--; ns.textContent = n; if (n <= 0){ clearInterval(iv); $('.sgx-rs', r).innerHTML = '<button style="color:var(--accent);font-weight:500">Resend code</button>'; } });
  });
  go.onclick = () => send(); em.onkeydown = e => { if (e.key === 'Enter') send(); };
  $('.sgx-bk', r).onclick = () => { s2.hidden = true; s1.hidden = false; s1.classList.remove('in'); void s1.offsetWidth; s1.classList.add('in'); go.textContent = 'Send code'; ins.forEach(i => i.value = ''); };
  let checking = false;
  /* verifying, then each digit turns green in turn, then the confirmed screen */
  function check(){ if (checking || !ins.every(i => i.value)) return; checking = true; c.run(async () => {
    const rs = $('.sgx-rs', r); ins.forEach(i => { i.blur(); i.readOnly = true; });
    code.classList.add('vf'); rs.innerHTML = '<span class="sgx-v"><span class="spin"></span>Verifying code</span>'; await c.wait(1100);
    code.classList.remove('vf'); code.classList.add('ok'); rs.innerHTML = `<span class="sgx-v ok">${I('check','xs')}Code confirmed</span>`; enter(rs.firstChild); await c.wait(1100);
    const card = $('.sgx', r); [...card.children].forEach(k => k.hidden = true);
    const d = html(`<div class="sgx-done"><svg class="sgx-ck" viewBox="0 0 52 52" aria-hidden="true"><circle cx="26" cy="26" r="24"/><path d="m16 27 7 7 13-14"/></svg><b>You're in</b><span class="muted">Opening your workspace</span><span class="sgx-bar"><i></i></span></div>`);
    card.appendChild(d); stagger([...d.children].slice(1), 90, 250); }); }
  /* clicking the code fills the rest from the email, one digit at a time */
  const fill = () => c.run(async () => { if (checking) return; for (let j = 0; j < 6; j++){ if (ins[j].value) continue; ins[j].value = CODE[j]; ins[j].classList.add('f'); const el = ins[j]; c.later(160, () => el.classList.remove('f')); await c.wait(110); } check(); });
  code.onpointerdown = e => { if (!ins.every(i => i.value)){ e.preventDefault(); fill(); } };
  ins.forEach((i, k) => {
    i.oninput = () => { i.value = i.value.replace(/\D/g, '').slice(-1); if (i.value){ i.classList.add('f'); c.later(150, () => i.classList.remove('f')); if (ins[k + 1]) ins[k + 1].focus(); } check(); };
    i.onkeydown = e => { if (e.key === 'Backspace' && !i.value && ins[k - 1]){ ins[k - 1].focus(); ins[k - 1].value = ''; } };
    i.onpaste = e => { const t = (e.clipboardData.getData('text') || '').replace(/\D/g, '').slice(0, 6); if (!t) return; e.preventDefault(); t.split('').forEach((d, j) => { if (ins[j]) ins[j].value = d; }); ins[Math.min(5, t.length)].focus(); check(); };
  });
  c.later(1000, () => c.run(async () => { for (const ch of 'maya@studio.com'){ em.value += ch; await c.wait(40); } await c.wait(300); send(true); await c.wait(1400); for (const [j, d] of [...CODE.slice(0, 4)].entries()){ ins[j].value = d; ins[j].classList.add('f'); c.later(150, () => ins[j].classList.remove('f')); await c.wait(160); } }));
});
